import {content as C} from './content.mjs';
export const escape = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape, A='/assets/ai4life/', money=n=>new Intl.NumberFormat('vi-VN').format(n)+' đồng';
const icon=(name='spark')=>{const paths={spark:'M12 3v4m0 10v4M3 12h4m10 0h4M6 6l3 3m6 6 3 3M6 18l3-3m6-6 3-3',calendar:'M5 5h14v16H5zM8 3v4m8-4v4M5 10h14',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-13a4 4 0 0 1 0 8m6 5v-2a4 4 0 0 0-3-3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8',cup:'M7 3h10v7a5 5 0 0 1-10 0V3ZM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 3v5m-4 1h8',book:'M12 5C7 2 3 3 3 3v16s4-1 9 2c5-3 9-2 9-2V3s-4-1-9 2Zm0 0v16',code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',mail:'M3 5h18v14H3zM3 5l9 8 9-8',check:'m5 12 4 4L19 6',menu:'M4 6h16M4 12h16M4 18h16',chevron:'m6 9 6 6 6-6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.spark).split('!').map(p=>`<path d="${p}"/>`).join('')}</svg>`;};
const stripes='<span class="stripes" aria-hidden="true"><i></i><i></i><i></i></span>';
export const link=(href,label,style='text-link')=>`<a class="${style}" href="${e(href)}" ${/^https:/.test(href)?'target="_blank" rel="noopener noreferrer"':''}>${e(label)}</a>`;
const p=(text)=>`<p>${e(text)}</p>`, list=arr=>`<ul class="clean-list">${arr.map(x=>`<li>${icon('check')}<span>${e(x)}</span></li>`).join('')}</ul>`;
export function localDate(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:C.event.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function registrationOpen(now=new Date()){return localDate(now)<=C.event.registrationDeadlineDate;}
export function countdown(now=Date.now()){const remaining=Math.max(0,Math.floor((Date.parse(C.nextMilestone.startsAt)-now)/1000));return {remaining,values:[Math.floor(remaining/86400),Math.floor(remaining%86400/3600),Math.floor(remaining%3600/60),remaining%60]};}
export const registration=(key)=>registrationOpen()?link(C.registration[key],`Đăng ký ${key==='aiForLife'?'AI for Life':'AI Challenge'}`,'button primary'):'<button class="button closed" disabled>Đã kết thúc đăng ký</button>';
const badge=(text,cls='')=>`<span class="badge ${cls}">${e(text)}</span>`;
const photo=(path,alt,cls='')=>{const a=C.gallery.find(x=>x.path===path);return `<img class="${cls}" src="${A+e(a?.thumbnail||path)}" alt="${e(alt)}" width="${a?.width||880}" height="${a?.height||600}" loading="lazy" decoding="async">`;};
export const pageTitles={'/':'Danang AI4Life 2026','/gioi-thieu':'Giới thiệu Danang AI4Life','/bang-thi/ai-for-life':'AI for Life','/bang-thi/ai-challenge':'AI Challenge','/the-le':'Thể lệ cuộc thi','/dang-ky':'Đăng ký tham gia','/lich-trinh':'Lịch trình cuộc thi','/giai-thuong':'Giải thưởng và quyền lợi','/ban-to-chuc':'Ban tổ chức và chuyên gia','/tin-tuc':'Tin tức cuộc thi','/ket-qua':'Dấu ấn cuộc thi','/thu-vien':'Thư viện hình ảnh','/tai-lieu':'Tài liệu cuộc thi','/dia-diem':'Địa điểm tổ chức','/lien-he':'Liên hệ Ban tổ chức'};
C.news.forEach(n=>pageTitles['/tin-tuc/'+n.slug]=n.title);
const navGroups={tracks:[['/bang-thi/ai-for-life','AI for Life'],['/bang-thi/ai-challenge','AI Challenge'],['/the-le','Thể lệ'],['/dang-ky','Đăng ký tham gia']],info:[['/giai-thuong','Giải thưởng'],['/ban-to-chuc','Ban tổ chức và chuyên gia'],['/tin-tuc','Tin tức'],['/ket-qua','Dấu ấn cuộc thi'],['/thu-vien','Thư viện hình ảnh'],['/tai-lieu','Tài liệu'],['/dia-diem','Địa điểm']]};
export function header(path){const item=(href,name)=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${name}</a>`;const group=(id,title)=>`<div class="nav-group"><button aria-expanded="false" aria-controls="nav-${id}" data-disclosure="nav-${id}" class="${navGroups[id].some(([x])=>x===path)?'active':''}">${title}${icon('chevron')}</button><div id="nav-${id}" class="dropdown" hidden>${navGroups[id].map(([h,n])=>item(h,n)).join('')}</div></div>`;return `<a class="skip-link" href="#main-content">Bỏ qua điều hướng</a><header class="site-header"><div class="header-inner"><a href="/" class="brand" aria-label="Danang AI4Life 2026 – Trang chủ"><img src="${A}brand/vku-logo-original.svg" width="46" height="30" alt="VKU"><span><span class="brand-long">Danang </span>AI4Life</span><span class="year">2026</span></a><button class="menu-toggle" data-mobile aria-label="Mở menu điều hướng" aria-expanded="false" aria-controls="main-nav">${icon('menu')}</button><nav id="main-nav" aria-label="Điều hướng chính">${item('/','Trang chủ')}${item('/gioi-thieu','Giới thiệu')}${group('tracks','Bảng thi')}${item('/lich-trinh','Lịch trình')}${group('info','Thông tin')}${item('/lien-he','Liên hệ')}</nav></div></header>`;}
export function footer(){return `<footer><div class="container footer-grid"><div><h3>Danang AI4Life 2026</h3>${stripes}${p('Cuộc thi Trí tuệ nhân tạo và ứng dụng dành cho sinh viên VKU.')}<img class="footer-logo" src="${A}brand/vku-logo-original.svg" width="76" height="50" alt="VKU"></div><div><h4>Cuộc thi</h4>${[['/gioi-thieu','Giới thiệu'],['/#bang-thi','Bảng thi'],['/the-le','Thể lệ'],['/lich-trinh','Lịch trình'],['/giai-thuong','Giải thưởng']].map(([h,n])=>link(h,n)).join('')}</div><div><h4>Khám phá</h4>${[['/ban-to-chuc','Ban tổ chức'],['/tin-tuc','Tin tức'],['/ket-qua','Dấu ấn cuộc thi'],['/thu-vien','Hình ảnh'],['/tai-lieu','Tài liệu']].map(([h,n])=>link(h,n)).join('')}</div><div><h4>Liên hệ VKU</h4>${p(C.venue.address)}${contactLinks()}${link('/dia-diem','Địa điểm và chỉ đường')}</div></div><div class="container footer-bottom"><span>Danang AI4Life · VKU, Đại học Đà Nẵng</span><span>Học tập · Nghiên cứu · Ứng dụng</span></div></footer>`;}
const contactLinks=()=>`<div class="contact-links">${link('mailto:'+C.contact.institutionEmail,C.contact.institutionEmail)}${link('tel:'+C.contact.institutionPhoneTel,C.contact.institutionPhoneDisplay)}<div class="actions">${link(C.contact.website,'Website VKU')}${link(C.contact.facebook,'Facebook VKU')}</div></div>`;
const hero=(title,desc,extras='')=>`<div class="breadcrumb">${link('/','Trang chủ')}<span>/</span><span>${e(title)}</span></div><section class="page-hero"><span class="eyebrow">Danang AI4Life · VKU</span><h1 tabindex="-1">${e(title)}</h1>${stripes}${p(desc)}${extras}</section>`;
const sectionTone=id=>({ 'giai-thuong':'gold','co-cau':'gold','co-hoi':'gold','quyen-loi':'gold','to-chuc':'blue','ban-to-chuc':'blue','dong-hanh':'blue','chuyen-gia':'blue','lien-he':'blue','kenh-lien-he':'blue','tin-tuc':'red','tong-quan':'red','gioi-thieu':'red','bang-thi':'gold' }[id]||['red','gold','blue'][[...id].reduce((n,c)=>n+c.charCodeAt(0),0)%3]);
const section=(id,title,desc,body,href='',label='Xem chi tiết')=>`<section class="section section-tone-${sectionTone(id)}" id="${id}"><div class="section-heading"><div><h2>${e(title)}</h2>${stripes}${desc?p(desc):''}</div>${href?link(href,label):''}</div>${body}</section>`;
const card=(title,text,ico='spark')=>`<div class="card"><span class="icon-box">${icon(ico)}</span><h3>${e(title)}</h3>${p(text)}</div>`;
const intro1='Danang AI4Life là cuộc thi Trí tuệ nhân tạo và ứng dụng do Trường Đại học Công nghệ Thông tin và Truyền thông Việt – Hàn, Đại học Đà Nẵng tổ chức cho sinh viên VKU. Cuộc thi khuyến khích sinh viên chủ động đề xuất, xây dựng và cải tiến giải pháp AI để giải quyết các bài toán trong đời sống và phục vụ cộng đồng.';
const intro2='Mùa 2026 gồm hai bảng thi: AI for Life dành cho giải pháp, sản phẩm ứng dụng AI; AI Challenge dành cho các bài toán thử thách với đề bài và dữ liệu do Ban tổ chức cung cấp. Các đội có cơ hội học hỏi từ giảng viên, chuyên gia và phát triển ý tưởng theo hướng nghiên cứu, ứng dụng và đổi mới sáng tạo.';
const benefits=[['Tư vấn và định hướng','Các đội được tư vấn, định hướng chuyên môn bởi giảng viên và chuyên gia trong quá trình phát triển ý tưởng, giải pháp.'],['Nghiên cứu và hoàn thiện sản phẩm','Các đội vào chung kết hoặc có sản phẩm tiềm năng được hỗ trợ nghiên cứu, viết bài khoa học và hoàn thiện giải pháp.'],['Kết nối ứng dụng và ươm tạo','Các giải pháp có tiềm năng được hỗ trợ kết nối triển khai thực tế, đăng ký giải pháp hữu ích và phát triển theo hướng khởi nghiệp đổi mới sáng tạo.'],['Cơ hội tham gia sân chơi quốc tế','Các đội, sản phẩm phù hợp có cơ hội được đánh giá và lựa chọn tham gia APISI 2027 theo kế hoạch.']];
const trackData=[{key:'aiForLife',slug:'ai-for-life',title:'AI for Life',label:'Bảng sản phẩm ứng dụng',subtitle:'Sản phẩm ứng dụng trí tuệ nhân tạo',desc:'Đội thi chủ động đề xuất và phát triển giải pháp, sản phẩm AI trong các lĩnh vực như giáo dục, y tế, giao thông, tài chính, du lịch, nông nghiệp và các lĩnh vực khác nhằm phục vụ cộng đồng.',items:['Đề xuất ý tưởng gắn với một bài toán thực tiễn.','Phát triển, hoàn thiện và trình bày giải pháp hoặc sản phẩm.','Có thể chủ động mời 01–02 giảng viên hướng dẫn phù hợp chuyên môn.'],meta:'Sơ tuyển: 01–10/10/2026 · Lịch dự kiến',icon:'spark'},{key:'aiChallenge',slug:'ai-challenge',title:'AI Challenge',label:'Bảng thử thách',subtitle:'Thử thách trí tuệ nhân tạo',desc:'Đội thi xây dựng mô hình và giải pháp AI để giải quyết bài toán do Ban tổ chức cung cấp, trên bộ dữ liệu và yêu cầu cụ thể của thử thách.',items:['Thi theo hình thức hackathon, thời lượng 08 giờ.','Giải pháp được xếp hạng theo chỉ số đánh giá của thử thách.','Vòng bán kết tuyển chọn 05 đội tham dự Olympic AI miền Trung.'],meta:'Bán kết: 07:30, 10/10/2026 · K.D2.101–K.D2.104',icon:'code'}];
const trackCards=(register=false)=>`<div class="grid two">${trackData.map((t,i)=>`<article class="card track-card ${i?'red':''}"><div class="track-top"><span class="icon-box">${icon(t.icon)}</span><span class="eyebrow">${t.label}</span><span class="track-number" aria-hidden="true">0${i+1}</span></div><h3>${t.title}</h3><p class="track-subtitle">${t.subtitle}</p>${p(t.desc)}${list(t.items)}<div class="card-bottom"><p class="meta">${e(t.meta)}</p>${register?registration(t.key):''}${link('/bang-thi/'+t.slug,register?'Xem yêu cầu bảng thi':'Xem bảng '+t.title,'button outline')}</div></article>`).join('')}</div>`;
const dateText=s=>s?.split('-').reverse().join('/');
const milestoneDate = () => new Intl.DateTimeFormat('vi-VN',{timeZone:C.event.timezone,day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(C.nextMilestone.startsAt));
const milestoneTime = () => new Intl.DateTimeFormat('vi-VN',{timeZone:C.event.timezone,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(C.nextMilestone.startsAt));
const schedule=(key,short=false)=>`<div class="timeline">${C.schedule[key].filter(x=>!short||x.id!=='afl-training'&&x.id!=='challenge-olympic').map(x=>`<article><div class="timeline-date">${e(x.dateText)}${x.certainty==='planned'?badge('Dự kiến'):''}</div><h3>${e(x.title)}</h3>${x.location?p(x.location+' · '+x.teams+' đội tham gia bán kết'):''}${x.description?p(x.description):''}</article>`).join('')}</div>`;
const milestone=()=>`<div class="milestone"><span class="eyebrow">Mốc gần nhất</span><h3>${e(C.nextMilestone.title)}</h3><p><strong>${milestoneTime()}, ngày ${milestoneDate()}</strong><br>${e(C.nextMilestone.location)}</p><div class="countdown" data-countdown aria-label="Bán kết AI Challenge, 07 giờ 30 ngày 10 tháng 10 năm 2026, tại K.D2.101 đến K.D2.104"></div>${link('/lich-trinh','Xem lịch trình')}</div>`;
const prizes=(full=false)=>`<div class="card prize-card"><div class="prize-heading"><span class="icon-box gold">${icon('cup')}</span><div><h3>Cơ cấu giải thưởng</h3>${badge('Dự kiến')}</div></div><div class="table-wrap"><table><caption class="sr-only">Cơ cấu giải thưởng dự kiến áp dụng chung cho hai bảng thi</caption><thead><tr><th scope="col">Giải thưởng</th><th scope="col">Số lượng</th><th scope="col">Giá trị mỗi giải</th>${full?'<th scope="col">Tổng giá trị</th>':''}</tr></thead><tbody>${C.prizes.map(x=>`<tr><th scope="row">${e(x.name)}</th><td>${String(x.quantity).padStart(2,'0')}</td><td>${money(x.amountVnd)}</td>${full?`<td>${money(x.amountVnd*x.quantity)}</td>`:''}</tr>`).join('')}</tbody></table></div><div class="prize-total"><span>Tổng giá trị theo cơ cấu dự kiến</span><strong>${money(C.prizes.reduce((s,x)=>s+x.quantity*x.amountVnd,0))}</strong></div></div>`;
const prizeNotes=()=>`<div class="callout"><h3>Điều kiện giải Đặc biệt</h3>${p('Giải Đặc biệt dành cho sản phẩm hoàn thiện theo hướng dự án khởi nghiệp đổi mới sáng tạo, đã triển khai thực tế và có số lượng người sử dụng lớn.')}${p('Số giải Khuyến khích có thể thay đổi theo số đội dự thi vòng chung kết. Các giải khác, nếu có, được công bố tại lễ bế mạc và trao giải.')}</div>`;
const people=arr=>`<div class="grid three">${arr.map(x=>`<article class="card person">${x.image?photo(x.image,x.name):`<span class="icon-box">${icon('people')}</span>`}<span class="meta">${e(x.institution)}</span><h3>${e(x.name)}</h3><p>${e(x.role)}</p></article>`).join('')}</div>`;
const partners=()=>`<div class="partner-grid">${C.partners.map(x=>`<div class="partner"><span>${e(x.group)}</span><strong>${e(x.name)}</strong></div>`).join('')}</div>`;
const units=['Phòng Khoa học công nghệ và Hợp tác quốc tế','Khoa Khoa học máy tính','Khoa Trí tuệ nhân tạo và Khoa học dữ liệu'];
const docs=()=>`<div class="grid two">${[['ke-hoach','Kế hoạch tổ chức Danang AI4Life 2026','Đối tượng, lịch dự kiến, quyền lợi, trách nhiệm và cơ cấu giải thưởng.','Văn bản ngày 14/09/2026','Tải kế hoạch'],['the-le','Thể lệ và yêu cầu Danang AI4Life 2026','Quy định chung, yêu cầu từng bảng thi và tiêu chí đánh giá AI for Life.','Kèm kế hoạch ngày 14/09/2026','Tải thể lệ']].map(([id,title,desc,date,label])=>`<article class="card document-card"><span class="icon-box">${icon('file')}</span><div><span class="eyebrow">DOCX · 2026</span><h3>${title}</h3>${p(desc)}<p class="meta">${date}</p><a class="button outline" href="/documents/${id}-ai4life-2026.docx" download>${label}</a></div></article>`).join('')}</div>`;
const faqData=[['Ai có thể tham gia cuộc thi?','Cuộc thi dành cho sinh viên VKU và khuyến khích các đội có thành viên từ nhiều khoa, ngành. Sinh viên thực hiện Đồ án chuyên ngành 2 các ngành IT và AI phải tham gia AI for Life; sinh viên lớp học phần Học máy (1)_TA học kỳ 1 năm học 2026–2027 phải tham gia AI Challenge theo kế hoạch.','/the-le#doi-tuong','Xem chi tiết đối tượng'],['Một đội được đăng ký bao nhiêu thành viên?','Mỗi đội tối đa 03 thành viên. Sinh viên có thể phối hợp với thành viên thuộc nhiều khoa, ngành để phát triển giải pháp phù hợp.'],['Có thể tham gia cả hai bảng thi không?','Có. Một đội hoặc một cá nhân có thể đồng thời tham gia AI for Life và AI Challenge theo kế hoạch cuộc thi.'],['Hai bảng thi khác nhau như thế nào?','AI for Life tập trung vào giải pháp, sản phẩm AI do đội chủ động đề xuất cho bài toán thực tiễn. AI Challenge tổ chức theo hình thức hackathon, sử dụng đề bài, dữ liệu và yêu cầu do Ban tổ chức cung cấp; giải pháp được xếp hạng theo chỉ số đánh giá của thử thách.'],['Cuộc thi có quy định công nhận điểm học phần không?','Có. Kế hoạch 2026 quy định công nhận điểm theo nhóm học phần, đồ án, vòng thi và thành tích đạt được. Sinh viên cần đọc đúng nhóm đối tượng của mình và thực hiện theo hướng dẫn của giảng viên, khoa và đơn vị đào tạo.','/the-le#cong-nhan-diem','Đọc quy định công nhận điểm'],['Hiện còn đăng ký được không?',registrationOpen()?'Hạn đăng ký theo kế hoạch là ngày 30/09/2026. Đội chọn đúng bảng thi và thực hiện đăng ký qua biểu mẫu tương ứng.':'Hạn đăng ký theo kế hoạch là ngày 30/09/2026 và đã kết thúc. Nếu có điều chỉnh, website chỉ cập nhật sau khi có thông báo xác nhận từ Ban tổ chức.']];
const details=(title,body,id='')=>`<details ${id?`id="${id}"`:''}><summary>${e(title)}${icon('chevron')}</summary><div class="details-body">${body}</div></details>`;
const faq=()=>`<div class="faq">${faqData.map(([q,a,h,l])=>details(q,p(a)+(h?link(h,l):''))).join('')}</div>`;
export const newsCards=(arr=C.news)=>`<div class="grid three">${arr.map(n=>`<article class="card news-card"><a href="/tin-tuc/${n.slug}" tabindex="-1" aria-hidden="true">${n.image?photo(n.image,n.title):`<div class="calendar-art">${icon('calendar')}<strong>10.10</strong><span>Bán kết AI Challenge · 2026</span></div>`}</a><div class="card-content"><div class="news-meta">${badge(n.label)}<span>${n.dateLabel}: ${dateText(n.eventDate||n.publishedAt)}</span></div><h3>${link('/tin-tuc/'+n.slug,n.title,'heading-link')}</h3>${p(n.description)}${link('/tin-tuc/'+n.slug,'Đọc tiếp')}</div></article>`).join('')}</div>`;
export const galleryCards=arr=>`<div class="grid three gallery-grid">${arr.map(a=>`<figure class="gallery-item"><button class="image-button ${a.category==='Ấn phẩm'?'contain':''}" data-image="${a.id}" aria-label="Xem ảnh: ${e(a.title)}">${photo(a.path,a.alt)}</button><figcaption>${e(a.title)}<span>${a.year} · ${e(a.category)}</span></figcaption></figure>`).join('')}</div>`;
const featured=arr=>`<div class="grid two">${arr.filter(x=>x.award==='Nhất').map(x=>`<article class="card result-feature">${photo(x.image||(x.year===2024?'2024/winners-event-2024.jpg':'2025/ai4life-challenge-award-photo-2025.jpg'),x.image?'The Liems nhận giải với sản phẩm Anti Scam':`Trao giải ${x.track} mùa ${x.year}`)}<div class="card-content"><span class="eyebrow">${x.track} · Giải ${x.award} · ${x.year}</span><h3>${e(x.team)}</h3>${p(x.project||(x.track==='AI for Life'?'Đội đạt giải Nhất bảng sản phẩm ứng dụng AI.':'Đội đạt giải Nhất bảng thử thách AI.'))}</div></article>`).join('')}</div>`;
export const resultContent=arr=>{const hasProject=arr.some(x=>x.project);return featured(arr)+`<div class="card results-table table-wrap"><table><caption>Kết quả nổi bật được chọn</caption><thead><tr>${['Bảng thi','Giải','Đội',...(hasProject?['Sản phẩm']:[])].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${arr.map(x=>`<tr><td>${x.track}</td><td>${badge('Giải '+x.award)}</td><th scope="row">${e(x.team)}</th>${hasProject?`<td>${e(x.project||'')}</td>`:''}</tr>`).join('')}</tbody></table></div><div class="results-mobile">${arr.map(x=>`<article class="card">${badge(x.track+' · Giải '+x.award)}<h3>${e(x.team)}</h3>${x.project?p(x.project):''}</article>`).join('')}</div>`;};
const contactBlock=()=>`<div class="contact-panel grid split"><div><span class="eyebrow">Đơn vị tổ chức</span><h3>${e(C.venue.name)}, Đại học Đà Nẵng</h3>${p(C.venue.address)}<h4>Đơn vị phối hợp triển khai</h4>${list(units)}${link('/dia-diem','Địa điểm và chỉ đường','button outline')}</div><div><span class="eyebrow">Đầu mối cuộc thi</span><h3>${e(C.contact.eventPerson)}</h3>${p(C.contact.eventRole)}${contactLinks()}${link('/lien-he','Xem thông tin liên hệ')}</div></div>`;
const home=()=>`<section class="home-hero" id="tong-quan"><div class="hero-art" aria-hidden="true"><img src="/assets/ai4life/brand/dragon-bridge-hero.webp" width="1942" height="809" alt="" fetchpriority="high"><span class="fire-light"></span></div><span class="hero-watermark" aria-hidden="true">VKU</span><span class="hero-atmosphere" aria-hidden="true"></span><div class="container hero-inner"><div class="hero-main"><span class="eyebrow">VKU · Cuộc thi Trí tuệ nhân tạo và ứng dụng</span><h1 tabindex="-1">Danang <span>AI4Life</span> 2026</h1>${stripes}<p class="hero-lead">Ứng dụng trí tuệ nhân tạo để giải quyết các bài toán thực tiễn.</p>${p('Cuộc thi dành cho sinh viên VKU, tạo môi trường học tập, nghiên cứu và phát triển các giải pháp AI phục vụ cuộc sống; đồng thời tuyển chọn đội tham dự Olympic AI miền Trung.')}<div class="actions">${link('/#bang-thi','Khám phá hai bảng thi','button primary')}${link('/lich-trinh','Xem lịch trình','button outline')}</div><div class="registration-status">${badge(registrationOpen()?'Trong thời hạn đăng ký theo kế hoạch':'Đã kết thúc đăng ký','neutral')}<span>Hạn đăng ký theo kế hoạch: ${dateText(C.event.registrationDeadlineDate)}.</span></div><div class="hero-footnote"><span>Học tập</span><i></i><span>Nghiên cứu</span><i></i><span>Ứng dụng</span></div></div></div><div class="hero-scene-caption"><span>Cầu Rồng · Đà Nẵng</span></div></section><div class="container home-sections"><aside class="quick-info hero-context"><h3>Thông tin nhanh</h3><dl>${[['book','Đơn vị tổ chức','VKU, Đại học Đà Nẵng'],['people','Đối tượng','Sinh viên VKU'],['people','Quy mô đội','Tối đa 03 thành viên'],['code','Hình thức','02 bảng thi: AI for Life và AI Challenge']].map(([ico,t,d])=>`<div>${icon(ico)}<dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl>${milestone()}${link('/the-le','Đọc thể lệ cuộc thi')}</aside>`+
section('gioi-thieu','AI vì cuộc sống, sáng tạo từ giảng đường','',`<div class="grid split"><div>${p(intro1)}${p(intro2)}</div><aside class="callout warm"><span class="icon-box gold">${icon('people')}</span><h3>Khuyến khích hợp tác liên ngành</h3>${p('Sinh viên nhiều khoa, ngành và lĩnh vực có thể cùng lập đội. Mỗi đội tối đa 03 thành viên; một cá nhân hoặc đội thi có thể tham gia đồng thời cả hai bảng.')}</aside></div>`,'/gioi-thieu','Giới thiệu cuộc thi')+
section('bang-thi','Hai bảng thi, hai hướng tiếp cận AI','Chọn bảng thi phù hợp với mục tiêu học tập và định hướng phát triển của đội.',trackCards()+`<p class="meta">Nhóm sinh viên thuộc diện bắt buộc tham gia thực hiện theo kế hoạch học phần và đồ án năm học 2026–2027.</p>${link('/the-le#doi-tuong','Xem đối tượng và quy định công nhận điểm')}`)+
section('lich-trinh','Các mốc thời gian cần lưu ý','Lịch trình dự kiến theo kế hoạch cuộc thi 2026.',`<div class="grid two"><div class="card"><h3>AI for Life</h3>${schedule('aiForLife',true)}</div><div class="card"><h3>AI Challenge</h3>${schedule('aiChallenge',true)}${link('/lich-trinh#ai-challenge','Xem thông tin vòng Olympic')}</div></div>`,'/lich-trinh','Xem lịch trình đầy đủ')+
section('quyen-loi','Ghi nhận thành tích, phát triển tiềm năng','Cơ cấu giải thưởng dự kiến áp dụng chung cho hai bảng thi.',`<div class="grid two">${prizes()}<div class="benefit-list"><h3>Cơ hội học tập và phát triển</h3>${benefits.map(([t,b])=>`<div class="benefit">${icon('check')}<div><h4>${t}</h4>${p(b)}</div></div>`).join('')}<p class="meta">Việc lựa chọn và hỗ trợ thực hiện theo điều kiện, quy định và đánh giá của đơn vị tổ chức.</p>${link('/the-le#quyen-loi','Xem quyền lợi và trách nhiệm')}</div></div>${prizeNotes()}`,'/giai-thuong','Xem giải thưởng và quyền lợi')+
section('to-chuc','Ban tổ chức và đơn vị đồng hành','Kết nối chuyên môn từ nhà trường, đối tác học thuật và doanh nghiệp.',`<div class="grid split organization-intro"><div><h3>${e(C.venue.name)}, Đại học Đà Nẵng</h3>${list(units)}</div><figure>${photo('2025/partners-event-2025.jpg','Các đơn vị đồng hành cùng cuộc thi')}<figcaption>Đồng hành cùng Danang AI4Life</figcaption></figure></div>${people([C.people[0],C.people[3],{...C.people[2],role:'Đầu mối triển khai'}])}${partners()}`,'/ban-to-chuc','Xem ban tổ chức và chuyên gia')+
section('tin-tuc','Thông báo và hoạt động','Theo dõi các mốc triển khai và hoạt động nổi bật của cuộc thi.',newsCards(),'/tin-tuc','Xem tất cả tin tức')+
section('dau-an','Dấu ấn cuộc thi','Những đội thi và sản phẩm tiêu biểu trong hành trình Danang AI4Life.',featured(C.pastResults.filter(x=>x.year===2025)),'/ket-qua','Xem các đội và sản phẩm nổi bật')+
section('hinh-anh','Khoảnh khắc Danang AI4Life','Hình ảnh giao lưu, thi đấu và ghi nhận thành tích tại VKU.',galleryCards(['opening-overview-2025','judges-event-2025','partners-event-2025','the-liems-award-2025','closing-overview-2025','winners-event-2024'].map(id=>C.gallery.find(a=>a.id===id))),'/thu-vien','Xem toàn bộ thư viện')+
section('tai-lieu','Tài liệu cuộc thi','Đọc kế hoạch và thể lệ để chuẩn bị đúng yêu cầu của bảng thi.',docs(),'/tai-lieu','Xem tài liệu cuộc thi')+
section('cau-hoi','Câu hỏi thường gặp','Những thông tin cần biết trước khi tham gia.',faq())+
section('lien-he','Đơn vị tổ chức và liên hệ','Kết nối với VKU để được hướng dẫn.',contactBlock())+'</div>';
const rubric=(key,title)=>`<div class="rubric-block"><h3>${title}</h3><div class="table-wrap"><table><caption class="sr-only">${title}</caption><thead><tr><th scope="col">Tiêu chí</th><th scope="col">Trọng số</th></tr></thead><tbody>${C.rubrics[key].items.map(x=>`<tr><td>${e(x.criterion)}</td><td><strong>${x.weight}%</strong><span class="weight-bar" style="--weight:${x.weight}%"></span></td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Tổng trọng số</th><td>100%</td></tr></tfoot></table></div></div>`;
const infoAside=t=>`<aside class="card sticky"><h3>Thông tin bảng thi</h3>${list(['Tối đa 03 thành viên/đội',t.key==='aiForLife'?'Có thể mời 01–02 giảng viên hướng dẫn':'Hackathon, 08 giờ',t.key==='aiForLife'?'Đối tượng: Sinh viên VKU':'Tuyển chọn 05 đội theo kế hoạch'])}<p class="meta">Hạn đăng ký: 30/09/2026</p>${registration(t.key)}<div class="aside-links">${link('/lich-trinh#'+t.slug,'Xem lịch trình')}${link('/documents/the-le-ai4life-2026.docx','Tải thể lệ 2026')}${link('/the-le#cong-nhan-diem','Xem quy định công nhận điểm')}</div>${p(t.key==='aiForLife'?'Sinh viên thực hiện Đồ án chuyên ngành 2 các ngành IT và AI thuộc nhóm bắt buộc tham gia theo kế hoạch.':'Sinh viên lớp học phần Học máy (1)_TA học kỳ 1 năm học 2026–2027 thuộc nhóm bắt buộc tham gia theo kế hoạch.')}</aside>`;
const trackPage=key=>{const t=trackData.find(x=>x.key===key),life=key==='aiForLife';return hero(t.title,t.subtitle,`<div class="actions">${badge(t.label)}${link('/bang-thi/'+(life?'ai-challenge':'ai-for-life'),'Xem bảng '+(life?'AI Challenge':'AI for Life'),'button outline')}</div>`)+`<div class="article-layout"><article>${life?section('dinh-huong','Định hướng dự thi','',p('Các đội đề xuất giải pháp, sản phẩm ứng dụng trí tuệ nhân tạo trong sản xuất, kinh doanh, giao thông, tài chính, y tế, giáo dục, du lịch, nông nghiệp và các lĩnh vực khác. Nội dung không giới hạn ở các lĩnh vực gợi ý, nhưng cần thể hiện rõ bài toán, cách ứng dụng AI và giá trị của giải pháp.')+p('Đội có thể ứng dụng xử lý ngôn ngữ tự nhiên, thị giác máy tính, phân tích dữ liệu, học máy, học sâu và các công nghệ AI phù hợp để xây dựng sản phẩm. Mỗi đội có thể chủ động liên hệ mời 01–02 giảng viên hướng dẫn theo chuyên môn của giải pháp.'))+section('linh-vuc','Lĩnh vực và công nghệ gợi ý','Danh mục tham khảo theo thể lệ, không phải giới hạn bắt buộc của đề tài.',`<div class="grid two">${[['Tối ưu hóa và phần mềm thông minh','Bài toán tối ưu hóa; tối ưu hóa và công nghệ phần mềm thông minh.'],['Thị giác máy tính và y sinh','Nhận dạng đối tượng, trích chọn đặc trưng và nhận dạng người; phân tích dữ liệu hình ảnh; tin học y sinh và xử lý ảnh phục vụ chẩn đoán.'],['Hệ thống thông minh','Giao thông thông minh, xe/robot/drone tự hành, điện toán biên thông minh và các hệ thống đeo bám mục tiêu.'],['Mạng và hạ tầng','Mạng phức hợp, đánh giá tính bền vững và khả năng hồi phục của hệ thống mạng.'],['Ngôn ngữ và dữ liệu','Xử lý ngôn ngữ tự nhiên, mô hình ngôn ngữ lớn, phân tích dữ liệu, học máy và học sâu.'],['Lĩnh vực ứng dụng khác','AI và vi mạch bán dẫn; AI và công nghệ tài chính; AI và thương mại điện tử.']].map(([a,b])=>card(a,b)).join('')}</div>`+details('Ví dụ kỹ thuật được nêu trong thể lệ',p('Text-To-Speech, Speech-To-Text, Sentiment Analysis, Topic Modelling, Chatbot, Text Classification, Image Recognition, Voice Recognition, Image Classification, Event Detection, Self-driving Car, Data Warehouse, Data Lake, Data Lakehouse, Data Ingestion, Data Visualisation, Time Series Data Analysis, Linear Regression, Reporting và các công nghệ AI khác.'))):section('hinh-thuc','Hình thức và nhiệm vụ','',p('AI Challenge được tổ chức theo hình thức hackathon. Ban tổ chức cung cấp đề bài, bộ dữ liệu và các yêu cầu cụ thể cho các đội đăng ký. Đội thi sử dụng công cụ, mô hình và giải pháp AI do đội đề xuất, xây dựng để giải quyết bài toán; kết quả được xếp hạng theo chỉ số đánh giá của thử thách.')+p('Nhiệm vụ có thể bao gồm gán nhãn và tiền xử lý dữ liệu; xây dựng mô hình phân tích và phán đoán từ dữ liệu; huấn luyện mô hình; ứng dụng mô hình để suy luận hoặc dự báo. Các kỹ thuật có thể liên quan đến xử lý ngôn ngữ tự nhiên, thị giác máy tính, phân tích dữ liệu, học máy và học sâu.')+`<div class="callout"><h3>Hackathon · ${String(C.challenge.durationHours).padStart(2,'0')} giờ</h3>${p('Định hướng thử thách: '+C.challenge.themes.join(' và '))}</div>`)}${section('lo-trinh',life?'Các vòng thi':'Lộ trình bảng thi','',schedule(key)+(life?'':p('Theo kế hoạch, điểm tại kỳ thi Olympic sinh viên AI miền Trung được sử dụng để xếp hạng Nhất, Nhì, Ba của bảng AI Challenge.')))}${section('tieu-chi','Tiêu chí đánh giá','',life?rubric('aiForLifePreliminary','Vòng sơ tuyển')+rubric('aiForLifeSemifinalFinal','Vòng bán kết và chung kết'):p('Giải pháp được xếp hạng theo chỉ số đánh giá của các thử thách. Đề bài, dữ liệu và yêu cầu cụ thể được Ban tổ chức gửi trực tiếp cho các đội đăng ký.')+p('Bên cạnh kết quả theo chỉ số của thử thách, giải pháp và phần trình bày được xem xét theo các tiêu chí chuyên môn.')+rubric('aiChallengeExpert','Tiêu chí đánh giá giải pháp và phần trình bày'))}${section('chuan-bi',life?'Yêu cầu cần lưu ý':'Chuẩn bị và tuân thủ','',list(life?['Ý tưởng, giải pháp và sản phẩm phải thuộc quyền sở hữu trí tuệ của đội, bảo đảm bản quyền và liêm chính học thuật.','Thực hiện đăng ký theo đúng mẫu của Ban tổ chức và chuẩn bị nội dung theo yêu cầu của từng vòng thi.','Đọc quy định chung về sản phẩm dự thi, tranh chấp bản quyền và trách nhiệm tham gia.']:['Đọc kỹ đề bài, dữ liệu và yêu cầu do Ban tổ chức cung cấp.','Bảo đảm quyền sở hữu và liêm chính học thuật của giải pháp dự thi.','Tham gia các vòng thi và tập huấn theo thông báo phù hợp.'])+link('/the-le#quy-dinh-chung','Đọc thể lệ chung'))}</article>${infoAside(t)}</div>`;};
const creditIntro='Quy định áp dụng theo nhóm đối tượng và học phần/đồ án trong kế hoạch năm học 2026–2027. Sinh viên cần đối chiếu văn bản nguồn và hướng dẫn của giảng viên, khoa, đơn vị đào tạo.';
const credits=()=>details('AI for Life — nhóm Đồ án chuyên ngành 2 IT và AI',list(['Không tham gia hoặc tham gia không nghiêm túc (không đăng ký; sản phẩm sơ tuyển sơ sài/sao chép; được chọn nhưng không trình bày ở các vòng thi): tối đa 50% điểm hướng dẫn Đồ án chuyên ngành 2.','Được chọn vào bán kết: điểm hướng dẫn mức A, từ 8,5 đến 10, theo đánh giá của giảng viên hướng dẫn.','Vào chung kết: điểm giảng viên hướng dẫn là 10.','Điểm bảo vệ đồ án được công nhận: Giải Nhì trở lên: 10; Giải Ba: 9,5; Giải Khuyến khích: 9,0.','Đề tài không vào chung kết vẫn phải tham gia bảo vệ Đồ án chuyên ngành 2 ngành IT, AI và được tối đa 9,0 theo kế hoạch.']),'diem-ai-for-life')+details('AI Challenge — nhóm Học máy (1)_TA',list(['Không tham gia hoặc tham gia không nghiêm túc (không đăng ký; được chọn nhưng không tham gia các vòng): tối đa 50% điểm chuyên cần theo thực tế đạt được; tối đa 50% cột điểm Bài tập; tối đa 50% cột điểm Giữa kỳ.','Top 10: điểm bài tập và giữa kỳ mức A trong khoảng 9,0–9,5; Top 5: trong khoảng 9,5–10, theo đánh giá của giảng viên giảng dạy học phần. Nhóm Top 5 sử dụng khoảng điểm dành riêng cho Top 5.','Đạt giải Khuyến khích trở lên tại chung kết: điểm bài tập và giữa kỳ là 10.','Điểm thi cuối kỳ được công nhận: Giải Nhì trở lên: 10; Giải Ba: 9,5; Giải Khuyến khích: 9,0.'])+p('Phạm vi Top 10 và Top 5 được nêu trong kế hoạch; mức điểm cụ thể thực hiện theo đánh giá của giảng viên.'),'diem-ai-challenge')+details('Sinh viên thuộc nhóm được khuyến khích',list(['Sinh viên thực hiện Đồ án chuyên ngành 2 các ngành khác được khuyến khích và công nhận điểm tương tự nhóm IT và AI cho bảng AI for Life theo kế hoạch.','Sinh viên các lớp Học máy khác, Xử lý ngôn ngữ tự nhiên, chuyên đề Phân tích dữ liệu và Thị giác máy tính vào Top 10 AI Challenge được công nhận điểm bài tập và giữa kỳ cho một trong các học phần nêu trên theo quy định.','Giải Ba được cộng 01 điểm cuối kỳ; Giải Nhì trở lên được cộng 02 điểm cuối kỳ theo kế hoạch.'])+p('Việc áp dụng học phần, thang điểm và thủ tục công nhận thực hiện theo hướng dẫn của khoa và đơn vị đào tạo; không suy diễn thêm cách cộng điểm vượt thang điểm từ nội dung website.'),'diem-khuyen-khich');
const rights=['Được tư vấn, hướng dẫn viết bài báo khoa học gửi hội thảo và tạp chí.','Được đánh giá, lựa chọn tham gia cuộc thi ươm mầm khởi nghiệp và đổi mới sáng tạo Đông Nam Á – APISI 2027.','Được vinh danh, cấp giấy chứng nhận và trao giải thưởng nếu đạt thành tích cao tại lễ bế mạc, trao giải.','Được kết nối với chuyên gia, nhà khoa học để tiếp tục hoàn thiện thuật toán và giải pháp.','Có thể được hỗ trợ giới thiệu giải pháp tới đơn vị ứng dụng AI, nếu cá nhân/đơn vị đạt giải có nhu cầu, nhằm phát triển sản phẩm triển khai thực tế.','Được hỗ trợ, tạo điều kiện đăng ký giải pháp hữu ích và ươm tạo sản phẩm tiềm năng từ thuật toán, giải pháp đạt giải.'];
const ruleItems=[['Sản phẩm dự thi','Giải pháp, sản phẩm không được đồng thời tham dự cuộc thi khác có cùng hoặc tương tự nội dung, tính chất; đồng thời chưa từng đạt giải tại các cuộc thi trước đó.'],['Quyền sở hữu và liêm chính','Giải pháp, sản phẩm phải thuộc quyền sở hữu trí tuệ của cá nhân hoặc nhóm đăng ký. Đội thi tự chịu trách nhiệm về bản quyền và liêm chính học thuật.'],['Khiếu nại sau trao giải','Người nhận giải có trách nhiệm giải quyết khiếu nại liên quan đến ý tưởng, sản phẩm. Nếu có bằng chứng xác thực về vi phạm thể lệ, Ban tổ chức có quyền thu hồi giải thưởng và xử lý theo quy định hiện hành của Nhà trường.'],['Tranh chấp bản quyền','Trong thời hạn 03 ngày (72 giờ) kể từ khi Ban tổ chức thông báo khiếu nại hoặc tranh chấp, tác giả/nhóm tác giả phải giải trình chứng minh quyền sở hữu. Nếu không có giải trình theo quy định, bài dự thi bị loại.'],['Tình huống phát sinh','Với vấn đề ngoài quy định hiện có, Ban tổ chức thảo luận và đưa ra quyết định.']];
const ruleToc=[['doi-tuong','Đối tượng'],['quy-dinh-chung','Quy định chung'],['tieu-chi','Tiêu chí đánh giá'],['quyen-loi','Quyền lợi'],['cong-nhan-diem','Công nhận điểm'],['trach-nhiem','Trách nhiệm tham gia']];
const rulesPage=()=>hero('Thể lệ cuộc thi','Đối tượng, quy định chung, tiêu chí đánh giá và quyền lợi, trách nhiệm của thí sinh Danang AI4Life 2026.')+`<div class="article-layout rules-layout"><article>${section('doi-tuong','Đối tượng và tổ chức đội thi','',p('Cuộc thi dành cho sinh viên VKU, khuyến khích sự kết hợp giữa các khoa, ngành, chuyên ngành và lĩnh vực. Mỗi đội tối đa 03 thành viên. Một cá nhân hoặc đội thi có thể tham gia đồng thời cả hai bảng.')+'<h3>Nhóm bắt buộc theo kế hoạch 2026</h3>'+`<div class="grid two">${card('AI for Life','Toàn bộ sinh viên thực hiện Đồ án chuyên ngành 2 các ngành IT và AI năm học 2026–2027 phải đăng ký tham gia.')}${card('AI Challenge','Toàn bộ sinh viên lớp học phần Học máy (1)_TA học kỳ 1 năm học 2026–2027 phải đăng ký tham gia. Kế hoạch cũng hướng đến các sinh viên có nguyện vọng tham dự Olympic AI miền Trung.')}</div><h3>Nhóm được khuyến khích</h3>`+list(['Sinh viên toàn trường có thể đăng ký theo định hướng và năng lực của đội.','Sinh viên thực hiện Đồ án chuyên ngành 2 các ngành khác được khuyến khích tham gia AI for Life và được xem xét công nhận điểm theo kế hoạch.','Sinh viên các lớp Học máy khác, Xử lý ngôn ngữ tự nhiên, chuyên đề Phân tích dữ liệu và Thị giác máy tính được khuyến khích tham gia AI Challenge; việc công nhận điểm áp dụng cho một học phần theo quy định.']))}${section('quy-dinh-chung','Quy định chung','',`<ol class="numbered-list">${ruleItems.map(([t,d])=>`<li><h3>${t}</h3>${p(d)}</li>`).join('')}</ol><p class="meta">Nội dung biên tập từ Thể lệ và yêu cầu cuộc thi 2026. Đọc văn bản nguồn để đối chiếu đầy đủ.</p>`+link('/documents/the-le-ai4life-2026.docx','Tải thể lệ 2026'))}${section('tieu-chi','Tiêu chí đánh giá theo bảng thi','',`<h3>AI for Life</h3>${rubric('aiForLifePreliminary','Vòng sơ tuyển')}${rubric('aiForLifeSemifinalFinal','Vòng bán kết và chung kết')}<h3>AI Challenge</h3>${p('Giải pháp được xếp hạng theo chỉ số đánh giá của các thử thách. Đề bài, dữ liệu và yêu cầu cụ thể được Ban tổ chức gửi trực tiếp cho các đội đăng ký.')}${rubric('aiChallengeExpert','Tiêu chí đánh giá giải pháp và phần trình bày')}`)}${section('quyen-loi','Quyền lợi','',p('Tất cả thí sinh có cơ hội được tư vấn, định hướng và hướng dẫn bởi chuyên gia trong lĩnh vực AI.')+'<h3>Đối với đội vào chung kết hoặc có giải pháp, sản phẩm tiềm năng</h3>'+list(rights))}${section('cong-nhan-diem','Quy định công nhận điểm',creditIntro,credits())}${section('trach-nhiem','Trách nhiệm tham gia','',p('Sinh viên và đội thi cần tham gia nghiêm túc, bảo đảm liêm chính học thuật và thực hiện các yêu cầu của vòng thi. Đối với sinh viên không thuộc nhóm bắt buộc, đăng ký nhưng bỏ không tham gia bán kết hoặc chung kết sẽ bị trừ điểm rèn luyện học kỳ 1 năm học 2026–2027 theo kế hoạch.')+link('/documents/ke-hoach-ai4life-2026.docx','Tải kế hoạch 2026'))}<div class="callout"><h3>Cần làm rõ trường hợp của bạn?</h3>${p('Liên hệ đầu mối cuộc thi hoặc giảng viên, khoa phụ trách học phần/đồ án để được hướng dẫn.')}${link('/lien-he','Thông tin liên hệ','button outline')}</div></article><aside class="card sticky toc"><h3>Mục lục</h3>${ruleToc.map(([id,t])=>link('#'+id,t)).join('')}${link('/documents/the-le-ai4life-2026.docx','Tải văn bản thể lệ','button outline')}</aside></div>`;
const aboutPage=()=>hero('Giới thiệu Danang AI4Life','Kết nối học tập, nghiên cứu và ứng dụng trí tuệ nhân tạo tại VKU.')+section('ai-vi-cuoc-song','AI vì cuộc sống','',`<div class="grid split"><div>${p(intro1)}${p(intro2)}</div><figure>${photo('2025/opening-overview-2025.jpg','Không gian giao lưu học thuật tại Danang AI4Life')}<figcaption>Không gian giao lưu học thuật tại Danang AI4Life</figcaption></figure></div>`)+section('muc-tieu','Mục tiêu cuộc thi','',`<div class="grid three">${[['Học tập và nghiên cứu','Khuyến khích sinh viên vận dụng kiến thức AI, phát triển năng lực nghiên cứu và chủ động giải quyết các bài toán thực tiễn.'],['Sáng tạo và ứng dụng','Tạo môi trường để hình thành, thử nghiệm và hoàn thiện các giải pháp, sản phẩm phục vụ đời sống và cộng đồng.'],['Kết nối và phát triển','Kết nối sinh viên với giảng viên, chuyên gia và doanh nghiệp; hỗ trợ các đội có tiềm năng phát triển nghiên cứu, ứng dụng và đổi mới sáng tạo.']].map(([a,b])=>card(a,b)).join('')}</div>`)+section('hai-huong','Hai hướng tham gia','',trackCards())+section('hanh-trinh','Hành trình Danang AI4Life','',`<div class="timeline">${[['2024','Khởi đầu','Cuộc thi lần đầu được tổ chức tại VKU, mở ra sân chơi học thuật về trí tuệ nhân tạo với hai bảng sản phẩm ứng dụng và thử thách AI.'],['2025','Tiếp nối và phát triển','Các đội tiếp tục đưa AI vào những bài toán thực tiễn, giao lưu cùng chuyên gia và doanh nghiệp, trình bày sản phẩm và tham gia thử thách tại vòng chung kết.'],['2026','Học tập gắn với ứng dụng','Hai bảng thi tiếp tục được tổ chức cho sinh viên VKU, gắn hoạt động dự thi với nghiên cứu, phát triển sản phẩm và tuyển chọn đội tham dự Olympic AI miền Trung.']].map(([y,t,d])=>`<article><span class="timeline-date">${y}</span><h3>${t}</h3>${p(d)}</article>`).join('')}</div><div class="actions">${link('/#bang-thi','Khám phá hai bảng thi','button primary')}${link('/ket-qua','Xem dấu ấn cuộc thi','button outline')}</div>`);
const schedulePage=()=>hero('Lịch trình cuộc thi','Theo dõi lộ trình hai bảng thi và chuẩn bị cho các vòng thi của Danang AI4Life 2026.',`<div class="actions">${link('#ai-for-life','AI for Life','button outline')}${link('#ai-challenge','AI Challenge','button outline')}</div>`)+`<div class="card milestone-wide">${milestone()}<div><span class="icon-box">${icon('calendar')}</span><h3>43 đội tham gia bán kết AI Challenge</h3>${p('07:30, ngày 10/10/2026 · K.D2.101–K.D2.104')}${link('/dia-diem','Xem địa điểm','button outline')}<p class="meta">Hạn đăng ký theo kế hoạch: 30/09/2026.</p>${badge('Đã kết thúc đăng ký','neutral')}</div></div>`+section('ai-for-life','AI for Life','Lịch dự kiến của bảng sản phẩm ứng dụng.',schedule('aiForLife'))+section('ai-challenge','AI Challenge','Bán kết, tập huấn và vòng Olympic.',schedule('aiChallenge'))+section('theo-doi','Theo dõi thông báo','',p('Lịch trình có thể được điều chỉnh theo kế hoạch triển khai. Sinh viên theo dõi thông báo của Ban tổ chức và hướng dẫn từ khoa, giảng viên phụ trách.')+`<div class="actions">${link(C.contact.website,'Website VKU','button outline')}${link(C.contact.facebook,'Facebook VKU','button outline')}${link('/documents/ke-hoach-ai4life-2026.docx','Tải kế hoạch','button outline')}</div>`);
const organizationPage=()=>hero('Ban tổ chức và chuyên gia','Nhà trường, chuyên gia học thuật và doanh nghiệp cùng hỗ trợ hành trình sáng tạo của sinh viên.',`<div class="actions">${[['to-chuc','Tổ chức'],['chuyen-gia','Chuyên gia'],['dong-hanh','Đồng hành']].map(([h,t])=>link('#'+h,t,'button outline')).join('')}</div>`)+section('to-chuc','Đơn vị tổ chức và triển khai','',`<div class="callout"><h3>${e(C.venue.name)}, Đại học Đà Nẵng</h3></div><div class="grid three">${units.map((t,i)=>card(t,['Điều phối triển khai theo kế hoạch cuộc thi.','Hướng dẫn chuyên môn và phối hợp tổ chức.','Hướng dẫn chuyên môn về AI và khoa học dữ liệu.'][i],'book')).join('')}</div>`)+section('ban-to-chuc','Ban tổ chức và đầu mối','',people(C.people.slice(0,3)))+section('chuyen-gia','Chuyên gia và đại diện đơn vị','Sự tham gia của các chuyên gia học thuật và doanh nghiệp góp phần kết nối nghiên cứu với những yêu cầu thực tiễn.',`<figure class="wide-photo">${photo('2025/judges-event-2025.jpg','Chuyên gia tham gia hoạt động cuộc thi')}</figure>`+people(C.people.slice(3)))+section('dong-hanh','Đơn vị đồng hành','',partners())+`<div class="callout"><h3>Tham gia hành trình AI tại VKU</h3><div class="actions">${link('/#bang-thi','Xem bảng thi','button primary')}${link('/lien-he','Liên hệ Ban tổ chức','button outline')}</div></div>`;
const prizesPage=()=>hero('Giải thưởng và quyền lợi','Ghi nhận thành tích, hỗ trợ học tập và phát triển các giải pháp AI có tiềm năng.')+section('co-cau','Cơ cấu giải thưởng dự kiến','Áp dụng chung cho hai bảng thi.',prizes(true)+prizeNotes())+section('co-hoi','Cơ hội học tập và phát triển','',`<div class="grid two">${benefits.map(([a,b])=>card(a,b)).join('')}</div>`)+`<div class="callout"><h3>Công nhận điểm học phần và đồ án</h3>${p('Cuộc thi có quy định công nhận điểm theo nhóm học phần, đồ án, vòng thi và thành tích. Sinh viên đọc đúng nhóm đối tượng của mình và thực hiện theo hướng dẫn của giảng viên, khoa, đơn vị đào tạo.')}${link('/the-le#cong-nhan-diem','Đọc quy định công nhận điểm','button outline')}</div><div class="actions">${link('/the-le','Xem thể lệ cuộc thi','button outline')}${link('/ket-qua','Dấu ấn các đội thi','button outline')}</div>`;
const registrationPage=()=>hero('Đăng ký tham gia','Chọn đúng bảng thi và chuẩn bị thông tin của đội trước khi thực hiện đăng ký.',`<div class="registration-status">${badge(registrationOpen()?'Trong thời hạn đăng ký theo kế hoạch':'Đã kết thúc đăng ký','neutral')}<span>Hạn đăng ký theo kế hoạch: ${dateText(C.event.registrationDeadlineDate)}.</span></div>`)+section('cac-buoc','Các bước tham gia','',`<div class="grid three steps">${[['Đọc yêu cầu','Tìm hiểu đối tượng tham gia, quy định chung và yêu cầu của từng bảng thi.'],['Thành lập đội','Mỗi đội tối đa 03 thành viên. Sinh viên có thể phối hợp giữa các khoa, ngành và lựa chọn bảng phù hợp với định hướng của đội.'],['Đăng ký đúng bảng','Thực hiện đăng ký qua biểu mẫu tương ứng, theo thông tin và yêu cầu trong biểu mẫu của Ban tổ chức.']].map(([t,d],i)=>`<article class="card"><span class="step-number">${i+1}</span><h3>${t}</h3>${p(d)}${i===0?link('/the-le','Đọc thể lệ'):''}</article>`).join('')}</div>`)+section('chon-bang','Chọn bảng thi','',trackCards(true))+section('chuan-bi','Chuẩn bị trước khi dự thi','',list(['Thống nhất tên đội và thông tin thành viên.','AI for Life: xác định bài toán, ý tưởng, công nghệ và định hướng sản phẩm; chuẩn bị nội dung theo yêu cầu biểu mẫu và từng vòng.','AI Challenge: tìm hiểu hình thức thử thách, chuẩn bị kiến thức và công cụ xử lý dữ liệu, xây dựng, đánh giá mô hình.','Đọc quy định về bản quyền, liêm chính học thuật và trách nhiệm tham gia.']))+`<div class="callout"><h3>Cần hướng dẫn thêm?</h3>${p('Theo dõi thông báo của VKU và liên hệ đầu mối cuộc thi để được hướng dẫn.')}<div class="actions">${link('/lien-he','Liên hệ Ban tổ chức','button primary')}${link('/tai-lieu','Tài liệu cuộc thi','button outline')}</div></div>`;
const filter=(key,title,options,value)=>`<label class="filter-label">${title}<select data-filter="${key}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
export function filterValues(path,params=new URLSearchParams()){let out={};const valid=(key,allowed,def)=>allowed.includes(params.get(key))?params.get(key):def;if(path==='/ket-qua')out={nam:valid('nam',['2025','2024'],'2025'),bang:valid('bang',['tat-ca','ai-for-life','ai-challenge'],'tat-ca')};if(path==='/thu-vien')out={nam:valid('nam',['tat-ca','2025','2024'],'tat-ca'),loai:valid('loai',['tat-ca','an-pham','hoat-dong','trao-giai'],'tat-ca')};if(path==='/tin-tuc')out={loai:valid('loai',['tat-ca','lich-su-kien','hoat-dong','ket-qua'],'tat-ca')};return out;}
const categoryMap={'an-pham':'Ấn phẩm','hoat-dong':'Hoạt động','trao-giai':'Trao giải','lich-su-kien':'Lịch sự kiện','ket-qua':'Kết quả'};
export function filteredContent(path,v){let rows=[];if(path==='/thu-vien')rows=C.gallery.filter(a=>(v.nam==='tat-ca'||a.year===Number(v.nam))&&(v.loai==='tat-ca'||a.category===categoryMap[v.loai]));if(path==='/tin-tuc')rows=C.news.filter(a=>v.loai==='tat-ca'||a.label===categoryMap[v.loai]);if(path==='/ket-qua')rows=C.pastResults.filter(a=>a.year===Number(v.nam)&&(v.bang==='tat-ca'||a.track===(v.bang==='ai-for-life'?'AI for Life':'AI Challenge')));if(!rows.length)return '<p class="empty-state" role="status">Không có nội dung phù hợp với bộ lọc này. Hãy chọn mùa hoặc loại nội dung khác.</p>';if(path==='/thu-vien')return galleryCards(rows);if(path==='/tin-tuc')return newsCards(rows);if(path==='/ket-qua')return resultContent(rows);return '';}
const newsPage=(v)=>hero('Tin tức cuộc thi','Thông báo, hoạt động và kết quả nổi bật của Danang AI4Life.')+`<div class="filters">${filter('loai','Loại nội dung',[['tat-ca','Tất cả'],['lich-su-kien','Lịch sự kiện'],['hoat-dong','Hoạt động'],['ket-qua','Kết quả']],v.loai)}</div><div data-filter-content>${filteredContent('/tin-tuc',v)}</div>`;
const resultsPage=v=>hero('Dấu ấn cuộc thi','Khám phá các đội và sản phẩm nổi bật của Danang AI4Life.')+`<div class="filters">${filter('nam','Mùa cuộc thi',[['2025','2025'],['2024','2024']],v.nam)}${filter('bang','Bảng thi',[['tat-ca','Tất cả'],['ai-for-life','AI for Life'],['ai-challenge','AI Challenge']],v.bang)}<span class="filter-note">Thành tích qua các mùa</span></div><div data-filter-content>${filteredContent('/ket-qua',v)}</div>`+section('ung-dung','Từ ý tưởng đến ứng dụng','Các đội được khuyến khích tiếp tục hoàn thiện giải pháp, phát triển nghiên cứu và tìm kiếm cơ hội ứng dụng thực tế.',`<figure data-results-year-photo>${photo(v.nam==='2024'?'2024/winners-event-2024.jpg':'2025/the-liems-award-2025.jpg','Vinh danh các đội thi mùa '+v.nam)}</figure><div class="actions">${link('/bang-thi/ai-for-life','Khám phá bảng AI for Life','button primary')}${link('/thu-vien','Xem thư viện hình ảnh','button outline')}</div>`);
const galleryPage=v=>hero('Thư viện hình ảnh','Ấn phẩm và hình ảnh hoạt động của Danang AI4Life tại VKU.')+`<div class="filters">${filter('loai','Loại hình ảnh',[['tat-ca','Tất cả'],['an-pham','Ấn phẩm'],['hoat-dong','Hoạt động'],['trao-giai','Trao giải']],v.loai)}${filter('nam','Mùa cuộc thi',[['tat-ca','Tất cả'],['2025','2025'],['2024','2024']],v.nam)}<span class="filter-note" data-filter-count aria-live="polite">16 ảnh và ấn phẩm</span></div><div data-filter-content>${filteredContent('/thu-vien',v)}</div>`;
const newsDetail=n=>hero(n.title,n.description,`<div class="news-meta">${badge(n.label)}<span>${n.dateLabel}: ${dateText(n.eventDate||n.publishedAt)}</span></div>`)+`<article class="news-article">${n.image?`<figure>${photo(n.image,n.title)}</figure>`:''}${n.slug==='ban-ket-ai-challenge-2026'?p('Bán kết AI Challenge được xếp lịch vào lúc 07:30 ngày 10/10/2026 tại các phòng K.D2.101–K.D2.104, VKU, với 43 đội thi.')+p('AI Challenge là bảng thi thử thách của Danang AI4Life. Các đội xây dựng mô hình và giải pháp AI theo đề bài, dữ liệu và yêu cầu do Ban tổ chức cung cấp; kết quả được xếp hạng theo chỉ số đánh giá của thử thách.')+section('thong-tin','Thông tin vòng thi','',`<dl class="event-dl">${[['Thời gian','07:30, 10/10/2026'],['Địa điểm',C.nextMilestone.location],['Đơn vị','VKU, Đại học Đà Nẵng'],['Số đội','43 đội tham gia bán kết']].map(([t,d])=>`<div><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl>`)+section('chuan-bi','Chuẩn bị và theo dõi','',p('Các đội đọc yêu cầu của bảng thi, chuẩn bị công cụ theo hướng dẫn của Ban tổ chức và theo dõi thông báo từ đơn vị phụ trách. Thông tin về thể lệ, lịch trình và địa điểm được trình bày tại các trang tương ứng.')+`<div class="actions">${link('/bang-thi/ai-challenge','Yêu cầu AI Challenge')}${link('/the-le','Thể lệ')}${link('/dia-diem','Địa điểm')}</div>`)+link(C.sources.calendar2026.url,'Lịch công tác VKU'):n.slug==='chung-ket-danang-ai4life-2025'?p('Vòng chung kết Danang AI4Life 2025 kết nối các đội sinh viên với giảng viên, chuyên gia và doanh nghiệp trong hoạt động học thuật về trí tuệ nhân tạo.')+p('Ở bảng AI for Life, các đội trình bày giải pháp, sản phẩm gắn với những bài toán thực tiễn. Bảng AI Challenge tổ chức các thử thách về thị giác máy tính và xử lý ngôn ngữ tự nhiên, tạo cơ hội vận dụng kiến thức vào xử lý dữ liệu và xây dựng mô hình.')+p('Sự tham gia của nhà trường, đối tác học thuật và doanh nghiệp góp phần tạo môi trường trao đổi chuyên môn, phản biện giải pháp và kết nối các hướng phát triển sản phẩm.')+p('Hoạt động chung kết thể hiện định hướng gắn học tập và nghiên cứu AI với ứng dụng. Những hình ảnh và kết quả nổi bật được lưu trong thư viện và chuyên mục dấu ấn cuộc thi.')+`<div class="actions">${link('/ket-qua?nam=2025','Dấu ấn mùa 2025')}${link('/thu-vien?nam=2025','Hình ảnh mùa 2025')}</div>`+link(C.sources.opening2025.url,'Đọc bài viết trên VKU'):p('Danang AI4Life 2025 ghi nhận thành tích của các đội ở hai bảng thi AI for Life và AI Challenge.')+p('Ở bảng AI for Life, The Liems đạt giải Nhất với sản phẩm Anti Scam; EduMate đạt giải Nhì với sản phẩm EduMate – Empowering the Modern Vietnamese Education.')+p('Ở bảng AI Challenge, Khỉ Con đạt giải Nhất, Cod 3 r đạt giải Nhì; Four Star và ClickSolve đạt giải Ba.')+p('Các kết quả cho thấy sự đa dạng trong cách tiếp cận AI của sinh viên, từ phát triển sản phẩm đến giải quyết thử thách dữ liệu và mô hình. Cuộc thi tiếp tục khuyến khích nghiên cứu, hợp tác và hoàn thiện các giải pháp phục vụ đời sống.')+`<div class="actions">${link('/ket-qua?nam=2025','Xem các đội nổi bật','button primary')}${link(C.sources.closing2025.url,'Đọc bài tổng kết trên VKU')}</div>`}<div class="related-news"><h2>Bài viết liên quan</h2>${stripes}${C.news.filter(x=>x.slug!==n.slug).map(x=>link('/tin-tuc/'+x.slug,x.title)).join('')}${link('/tin-tuc','Về tin tức','button outline')}</div></article>`;
const documentsPage=()=>hero('Tài liệu cuộc thi','Đọc kế hoạch, thể lệ và các tài liệu cần thiết để chuẩn bị đúng yêu cầu.')+section('tai-lieu','Văn bản cuộc thi 2026','Đọc kế hoạch và thể lệ trước khi chuẩn bị hồ sơ, sản phẩm dự thi.',docs())+`<div class="actions">${link('/the-le','Đọc thể lệ trên website','button primary')}${link('/dang-ky','Hướng dẫn đăng ký','button outline')}${link('/thu-vien?loai=an-pham','Xem ấn phẩm cuộc thi','button outline')}</div>`;
const venuePage=()=>hero('Địa điểm tổ chức','Thông tin địa chỉ VKU và địa điểm của mốc thi gần nhất.')+section('dia-chi','Địa chỉ và vòng thi','',`<div class="grid split"><div class="card"><span class="icon-box">${icon('pin')}</span><h3>VKU, Đại học Đà Nẵng</h3>${p(C.venue.name+', Đại học Đà Nẵng')}${p(C.venue.address)}${contactLinks()}</div><div class="card"><span class="icon-box">${icon('calendar')}</span><h3>Bán kết AI Challenge</h3>${list(['07:30, ngày 10/10/2026',C.nextMilestone.location,'43 đội tham gia vòng bán kết','Theo dõi hướng dẫn bố trí của đơn vị phụ trách'])}<div class="actions">${link('/lich-trinh#ai-challenge','Lịch AI Challenge')}${link('/bang-thi/ai-challenge','Yêu cầu bảng thi')}</div></div></div>`)+section('chi-duong','Chỉ đường đến VKU','Tìm đường đến VKU tại địa chỉ 470 Trần Đại Nghĩa, Đà Nẵng.',`<div class="map-card"><span class="icon-box">${icon('pin')}</span><div><h3>470 Trần Đại Nghĩa</h3>${p('Phường Ngũ Hành Sơn, thành phố Đà Nẵng')}${link(C.venue.mapUrl,'Mở Google Maps','button primary')}</div></div>`)+section('chuan-bi','Chuẩn bị trước khi đến','',list(['Kiểm tra lịch trình và thông báo của bảng thi','Đọc hướng dẫn về công cụ, hồ sơ hoặc sản phẩm cần chuẩn bị','Liên hệ đầu mối cuộc thi khi cần hỗ trợ'])+`<div class="actions">${link('/tai-lieu','Tài liệu cuộc thi','button outline')}${link('/lien-he','Thông tin hỗ trợ','button outline')}</div>`);
const contactPage=()=>hero('Liên hệ Ban tổ chức','Kênh hướng dẫn và thông tin về Danang AI4Life.')+section('kenh-lien-he','Kết nối với Ban tổ chức','',`<div class="grid split"><div class="card"><span class="icon-box">${icon('people')}</span><span class="eyebrow">Đầu mối cuộc thi</span><h3>${e(C.contact.eventPerson)}</h3>${p(C.contact.eventRole+', VKU')}${p('Liên hệ để được hướng dẫn về việc tham gia cuộc thi, lịch trình và các vấn đề trong quá trình triển khai.')}</div><div class="card"><span class="icon-box">${icon('mail')}</span><h3>Kênh liên hệ VKU</h3>${contactLinks()}</div></div>`)+section('dia-chi','Địa chỉ','',p(C.venue.address)+link('/dia-diem','Xem địa điểm và chỉ đường','button outline'))+`<div class="callout"><h3>Quy định công nhận điểm học phần</h3>${p('Sinh viên trao đổi với giảng viên, khoa và đơn vị đào tạo để được hướng dẫn áp dụng.')}${link('/the-le#cong-nhan-diem','Đọc quy định công nhận điểm','button outline')}</div>`;
export function renderPage(path,params=new URLSearchParams()){const v=filterValues(path,params);const routes={'/':home,'/gioi-thieu':aboutPage,'/bang-thi/ai-for-life':()=>trackPage('aiForLife'),'/bang-thi/ai-challenge':()=>trackPage('aiChallenge'),'/the-le':rulesPage,'/dang-ky':registrationPage,'/lich-trinh':schedulePage,'/giai-thuong':prizesPage,'/ban-to-chuc':organizationPage,'/tin-tuc':()=>newsPage(v),'/ket-qua':()=>resultsPage(v),'/thu-vien':()=>galleryPage(v),'/tai-lieu':documentsPage,'/dia-diem':venuePage,'/lien-he':contactPage};if(routes[path])return routes[path]();const n=C.news.find(n=>path==='/tin-tuc/'+n.slug);if(n)return newsDetail(n);return hero('Không tìm thấy trang','Trang bạn tìm kiếm không tồn tại.',link('/','Về trang chủ','button primary'));}
export const imageDialog=()=>`<dialog id="image-dialog" aria-modal="true" aria-labelledby="image-title"><div class="dialog-top"><h2 id="image-title">Hình ảnh cuộc thi</h2><button class="button outline" data-close>Đóng ảnh</button></div><div class="dialog-image"><img id="dialog-photo" alt=""></div><p id="image-caption"></p><div class="dialog-actions"><div class="actions"><button class="button outline" data-previous>Ảnh trước</button><button class="button outline" data-next>Ảnh sau</button></div><span id="image-position" role="status" aria-live="polite"></span><div class="actions"><a id="image-original" class="text-link" target="_blank" rel="noopener noreferrer">Mở ảnh gốc</a><a id="image-download" class="text-link" download>Tải ảnh</a></div></div></dialog>`;
